<?php $plan=plan((int)$user['id']);$sub=row("SELECT * FROM subscriptions WHERE user_id=? ORDER BY id DESC LIMIT 1",[$user['id']]);?><div class="grid grid-2"><div class="card"><span class="eyebrow">YOUR CURRENT PLAN</span><h2><?=e($plan['name'])?></h2><div class="price"><?=money((int)$plan['price'])?><small> / month</small></div><p>Status: <?=e($sub['status']??'Free')?> · Access until <?=e($sub['ends_at']??'No expiry')?></p><p class="small">Paid plans run for one month per payment. Renew manually before expiry. Cancelling immediately returns the account to Free limits.</p><button class="button secondary small-button" data-action="cancel-subscription" data-confirm="Cancel the paid subscription and return to Free limits now?">Cancel subscription</button></div><div class="card"><h3>Choose your next chapter.</h3><?php if(!cfg('RAZORPAY_KEY')):?><div class="alert">Payment provider not configured. Your administrator must enable Razorpay before checkout.</div><?php endif;?><form id="checkout-form"><label>Plan<select name="plan_id"><?php foreach(rows('SELECT * FROM plans WHERE price>0 AND active=1 ORDER BY price') as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> — <?=money((int)$p['price'])?> / month</option><?php endforeach;?></select></label><?php field('coupon','Coupon code','text','',false);?><button class="button">Continue to secure checkout ↗</button></form><p class="small">Plan activation occurs only after a verified payment webhook.</p></div></div><div class="card stack"><h3>Invoices & payment history</h3><?php table(['number'=>'Invoice','created_at'=>'Date','amount'=>'Amount (paise)','currency'=>'Currency','status'=>'Status','order_id'=>'Order'],rows('SELECT p.*,i.number FROM payments p LEFT JOIN invoices i ON i.payment_id=p.id WHERE p.user_id=? ORDER BY p.id DESC LIMIT 100',[$user['id']]));?></div><script src="https://checkout.razorpay.com/v1/checkout.js" defer></script><script src="<?=url('/assets/js/checkout.js')?>" defer></script>

<?php foreach(rows('SELECT i.id,i.number FROM invoices i JOIN payments p ON p.id=i.payment_id WHERE p.user_id=? ORDER BY i.id DESC LIMIT 100',[$user['id']]) as $invoice)echo '<p><a class="button secondary small-button" href="'.url('/invoice?id='.$invoice['id']).'">View invoice '.e($invoice['number']).' →</a></p>'; ?>